export class WorkflowBlueprint {
  readonly name: string
  readonly version: number
  /** The whole run's deadline, enforced by the engine; none by default. */
  readonly timeoutMs?: number
  readonly taskQueue: string
  private readonly nodes: InternalWorkflowNode[] = []
  private readonly queries = new Map<string, DataRef>()
  private readonly declaredSteps = new Set<string>()
  private continuation?: Record<string, unknown>
  private readonly changes = new Map<string, { min: number; max: number }>()
  private readonly updates = new Map<string, InternalUpdate>()
  private inScope = false

  constructor(
    name: string,
    options?: { version?: number; timeoutMs?: number; taskQueue?: string },
  ) {
    this.name = name
    this.version = options?.version ?? 1
    this.timeoutMs = options?.timeoutMs
    this.taskQueue = options?.taskQueue ?? 'workflows'
  }

  private validateAndRegister(stepName: string, inputSpec: unknown, after?: string[]): void {
    if (this.declaredSteps.has(stepName)) {
      throw new Error(`Duplicate workflow step '${stepName}' in workflow '${this.name}'`)
    }
    for (const dep of after ?? []) {
      if (!this.declaredSteps.has(dep)) {
        throw new Error(`Step '${stepName}' in workflow '${this.name}' waits (after) for unknown or downstream step '${dep}'`)
      }
    }
    for (const dep of extractStepDependencies(inputSpec)) {
      if (!this.declaredSteps.has(dep)) {
        throw new Error(`Step '${stepName}' in workflow '${this.name}' references unknown or downstream step '${dep}'`)
      }
    }
    this.declaredSteps.add(stepName)
  }

  private checkCondition(stepName: string, onlyIf?: DataRef): void {
    if (onlyIf === undefined || onlyIf === null) return
    if (!(onlyIf instanceof DataRef)) {
      throw new Error(`Step '${stepName}' in workflow '${this.name}': onlyIf must be a reference (input(), output(), ref())`)
    }
    for (const dep of extractStepDependencies(onlyIf)) {
      if (!this.declaredSteps.has(dep)) {
        throw new Error(`Step '${stepName}' in workflow '${this.name}': onlyIf refers to unknown or downstream step '${dep}'`)
      }
    }
  }

  query(name: string, expr: DataRef): this {
    this.queries.set(name, expr)
    return this
  }

  /** A step. `after` names earlier steps it also waits for (on top of what precedes it, e.g. a sibling in a
   * `parallel` group); `timeoutMs` limits one attempt, `heartbeatMs` how long the handler may go without calling
   * `ctx.heartbeat()`, `scheduleToStartMs` how long the step may wait for a worker; `onlyIf` (a reference) runs the
   * step only when it is truthy, else the step is skipped; `gate` (see `gate()`) runs it only on one side of a change.
   * The engine enforces them. */
  step<TPayload = any, TResult = unknown>(
    name: string,
    handler: TaskHandler<TPayload, TResult>,
    options?: WorkflowStepOption,
  ): this {
    this.checkCondition(name, options?.onlyIf)
    this.validateAndRegister(name, options?.input, options?.after)
    this.nodes.push({
      kind: 'step',
      name,
      handler,
      inputSpec: options?.input,
      retry: options?.retry,
      compensate: options?.compensate,
      after: [...(options?.after ?? [])],
      timeoutMs: options?.timeoutMs,
      heartbeatMs: options?.heartbeatMs,
      scheduleToStartMs: options?.scheduleToStartMs,
      onlyIf: options?.onlyIf,
      gate: options?.gate,
    })
    return this
  }

  /** A durable wait for `signal`. `after` names earlier steps it also waits for; `onlyIf` waits only when the
   * reference is truthy; `compensate` undoes it (its input defaults to the signal's payload) when the run fails. */
  waitFor(name: string, options: WaitForOption): this {
    this.checkCondition(name, options.onlyIf)
    this.validateAndRegister(name, undefined, options.after)
    this.nodes.push({
      kind: 'wait_for',
      name,
      signalName: options.signal,
      timeoutMs: options.timeoutMs ?? 600_000,
      after: [...(options.after ?? [])],
      onlyIf: options.onlyIf,
      compensate: options.compensate,
      gate: options.gate,
    })
    return this
  }

  /** A durable wait of `forMs`. `after` names earlier steps it also waits for; `onlyIf` waits only when the
   * reference is truthy; `compensate` undoes it (its input defaults to the timer's output) when the run fails. */
  timer(name: string, options: TimerOption): this {
    this.checkCondition(name, options.onlyIf)
    this.validateAndRegister(name, undefined, options.after)
    this.nodes.push({
      kind: 'timer',
      name,
      durationMs: options.forMs,
      after: [...(options.after ?? [])],
      onlyIf: options.onlyIf,
      compensate: options.compensate,
      gate: options.gate,
    })
    return this
  }

  /** Runs another workflow (a blueprint or its name) as a step; its output is the child run's output, its failure the
   * step's. The engine starts the child and resolves `input` (references only: `input()`, `output()`, `ref()`, in
   * objects and arrays; the run's input when omitted). A child is not retried: give the child's own steps retries, and
   * the child workflow a `timeoutMs`. The child workflow must be registered before a run reaches this step. No handler
   * runs in this worker for it. */
  child(name: string, workflowDef: WorkflowBlueprint | string, options?: ChildOption): this {
    if (options?.input !== undefined && options.input !== null) template(options.input, `${name}.input`)
    this.checkCondition(name, options?.onlyIf)
    this.validateAndRegister(name, options?.input, options?.after)
    this.nodes.push({
      kind: 'child',
      name,
      workflowName: workflowDef instanceof WorkflowBlueprint ? workflowDef.name : String(workflowDef),
      inputSpec: options?.input,
      compensate: options?.compensate,
      after: [...(options?.after ?? [])],
      onlyIf: options?.onlyIf,
      gate: options?.gate,
    })
    return this
  }

  /** When the run ends (and `onlyIf` is truthy), it closes `continued_as_new` and a fresh run of this workflow starts
   * with `input` (references only, resolved by the engine; the same input when omitted), at most `maxRuns` runs. */
  continueAsNew(options: ContinueAsNewOption = {}): this {
    const policy: Record<string, unknown> = {}
    if (options.input !== undefined && options.input !== null) policy.input = template(options.input, 'continue_as_new.input')
    if (options.onlyIf !== undefined && options.onlyIf !== null) {
      if (!(options.onlyIf instanceof DataRef)) {
        throw new Error('continueAsNew: onlyIf must be a reference (input(), output(), ref())')
      }
      policy.only_if = options.onlyIf.expr
    }
    if (options.maxRuns !== undefined && options.maxRuns !== null) policy.max_runs = options.maxRuns
    if (options.maxEvents !== undefined && options.maxEvents !== null) policy.max_events = options.maxEvents
    this.continuation = policy
    return this
  }

  /** Declares a change (versioning, like Temporal's getVersion): runs that reach a gated node fresh take `max`, runs
   * that went past it on the old path keep 0; nodes pick a side with `gate: gate(id, { min, max })`. Raise `min` only
   * once no open run is on an older path. */
  change(id: string, options: { min?: number; max?: number } = {}): this {
    const min = options.min ?? 0
    const max = options.max ?? 1
    if (min > max) throw new Error(`change '${id}' in workflow '${this.name}': min is above max`)
    this.changes.set(id, { min, max })
    return this
  }

  /** An update handler (`JoobQClient.updateWorkflow`): `validate` (a reference, e.g. `updateInput('name')`) must be
   * truthy or the update is rejected with `message`; then `handler` runs as a step of the run (its payload is `input`,
   * by default the update's input, and its return value is the result), or, without one, `result` (a template of
   * references) is the result. References may read the run (`input()`, `output()`) and `updateInput()`. */
  update(name: string, handler?: TaskHandler<any, any> | null, options: UpdateOption = {}): this {
    if (this.updates.has(name)) throw new Error(`Duplicate update '${name}' in workflow '${this.name}'`)
    if (options.validate !== undefined && options.validate !== null && !(options.validate instanceof DataRef)) {
      throw new Error(`update '${name}': validate must be a reference (updateInput(), input(), output(), ref())`)
    }
    if (options.input !== undefined && options.input !== null) template(options.input, `update ${name}.input`)
    if (options.result !== undefined && options.result !== null) template(options.result, `update ${name}.result`)
    this.updates.set(name, {
      name,
      handler: handler ?? undefined,
      validate: options.validate ?? undefined,
      message: options.message,
      input: options.input,
      result: options.result,
      timeoutMs: options.timeoutMs,
    })
    return this
  }

  /** A cancellation scope: its steps run in sequence and can be cancelled as a unit (from the console or API, or after
   * `timeoutMs` from its first step's start) while the rest of the run goes on; a cancelled step counts as finished
   * with a null output. A `nonCancellable` scope holds cleanup that still runs when the workflow is cancelled, times
   * out or fails (it cannot have a timeout). A running step sees a cancel through `ctx.heartbeat()`. Scopes do not
   * nest. */
  scope(name: string, build: (b: WorkflowBlueprint) => void, options: ScopeOption = {}): this {
    if (this.inScope) {
      throw new Error(`scope '${name}' in workflow '${this.name}' is inside another scope: scopes do not nest`)
    }
    if (options.nonCancellable && options.timeoutMs !== undefined && options.timeoutMs !== null) {
      throw new Error(`scope '${name}' is nonCancellable and cannot time out`)
    }
    const sub = this.group('scope', true)
    build(sub)
    if (sub.nodes.length === 0) throw new Error(`scope '${name}' in workflow '${this.name}' has no steps`)
    for (const s of sub.declaredSteps) this.declaredSteps.add(s)
    this.nodes.push({
      kind: 'scope',
      name,
      children: sub.nodes,
      timeoutMs: options.timeoutMs ?? undefined,
      nonCancellable: options.nonCancellable ? true : undefined,
    })
    return this
  }

  /** A builder for a group's children: it sees the steps declared so far. */
  private group(kind: string, inScope = this.inScope): WorkflowBlueprint {
    const sub = new WorkflowBlueprint(`${this.name}:${kind}`, {
      version: this.version,
      timeoutMs: this.timeoutMs,
      taskQueue: this.taskQueue,
    })
    for (const s of this.declaredSteps) sub.declaredSteps.add(s)
    sub.inScope = inScope
    return sub
  }

  parallel(build: (b: WorkflowBlueprint) => void): this {
    const sub = this.group('parallel')
    build(sub)
    for (const s of sub.declaredSteps) this.declaredSteps.add(s)
    this.nodes.push({ kind: 'parallel', name: `parallel_${this.nodes.length + 1}`, children: sub.nodes })
    return this
  }

  sequence(build: (b: WorkflowBlueprint) => void): this {
    const sub = this.group('sequence')
    build(sub)
    for (const s of sub.declaredSteps) this.declaredSteps.add(s)
    this.nodes.push({ kind: 'sequence', name: `sequence_${this.nodes.length + 1}`, children: sub.nodes })
    return this
  }

  /** The workflow's structure as data, as the worker registers it with the gateway (`CONTRACT.md`). */
  toBlueprint(): Record<string, unknown> {
    const node = (n: InternalWorkflowNode): Record<string, unknown> => {
      const out: Record<string, unknown> = { name: n.name, kind: n.kind }
      if (n.kind === 'parallel' || n.kind === 'sequence' || n.kind === 'scope') {
        out.children = (n.children ?? []).map(node)
        if (n.kind === 'scope') {
          if (n.timeoutMs !== undefined && n.timeoutMs !== null) out.timeout_ms = n.timeoutMs
          if (n.nonCancellable) out.non_cancellable = true
        }
      } else if (n.kind === 'wait_for') {
        out.signal = n.signalName
        out.timeout_ms = n.timeoutMs
      } else if (n.kind === 'timer') {
        out.for_ms = n.durationMs
      } else if (n.kind === 'child') {
        out.workflow = n.workflowName
        if (n.inputSpec !== undefined && n.inputSpec !== null) out.input = template(n.inputSpec, `${n.name}.input`)
      } else {
        out.activity = handlerName(n.handler)
        out.references = n.inputSpec === undefined || n.inputSpec === null ? ['${input}'] : collectReferences(n.inputSpec)
        if (n.timeoutMs !== undefined && n.timeoutMs !== null) out.timeout_ms = n.timeoutMs
        if (n.heartbeatMs !== undefined && n.heartbeatMs !== null) out.heartbeat_ms = n.heartbeatMs
        if (n.scheduleToStartMs !== undefined && n.scheduleToStartMs !== null) out.schedule_to_start_ms = n.scheduleToStartMs
        if (n.retry) out.retry = retryJson(n.retry)
      }
      if (n.kind !== 'parallel' && n.kind !== 'sequence' && n.kind !== 'scope') {
        // A step, wait, timer or child can be undone, made conditional and gated.
        if (n.compensate) {
          out.compensate = {
            activity: handlerName(n.compensate.handler),
            references: collectReferences(n.compensate.input ?? output(n.name)),
          }
        }
        if (n.onlyIf) out.only_if = n.onlyIf.expr
        if (n.gate) {
          const g: Record<string, unknown> = { change: n.gate.change }
          if (n.gate.min !== undefined && n.gate.min !== null) g.min = n.gate.min
          if (n.gate.max !== undefined && n.gate.max !== null) g.max = n.gate.max
          out.gate = g
        }
      }
      if (n.after && n.after.length > 0) out.after = [...n.after]
      return out
    }
    const blueprint: Record<string, unknown> = {
      name: this.name,
      version: this.version,
      task_queue: this.taskQueue,
      queries: Object.fromEntries([...this.queries.entries()].map(([k, v]) => [k, v.expr])),
      nodes: this.nodes.map(node),
    }
    // The whole run's deadline, enforced by the engine.
    if (this.timeoutMs !== undefined && this.timeoutMs !== null) blueprint.timeout_ms = this.timeoutMs
    if (this.continuation) blueprint.continue_as_new = { ...this.continuation }
    if (this.changes.size > 0) {
      blueprint.changes = [...this.changes.entries()].map(([id, b]) => ({ id, min: b.min, max: b.max }))
    }
    if (this.updates.size > 0) {
      blueprint.updates = Object.fromEntries([...this.updates.values()].map((u) => [u.name, updateSpec(u)]))
    }
    return blueprint
  }

  /** The handlers of this workflow's steps, by the activity name the engine sends them under (`<workflow>/<step>`,
   * compensations `<workflow>/<step>/compensate`, update handlers `<workflow>/@update/<name>`, which get their payload
   * as the engine resolved it). Each runs its step once: the engine conducts the run (it retries, compensates and
   * waits). A step's input is resolved against the run's input (the task's payload) and the outputs of the steps that
   * completed (the task's checkpoints). */
  activities(): Map<string, TaskHandler> {
    const found = new Map<string, TaskHandler>()
    const checkpointsOf = (ctx: ExecutionContext) => ctx.task.checkpoints ?? {}

    const visit = (nodes: InternalWorkflowNode[]): void => {
      for (const node of nodes) {
        if (node.kind === 'sequence' || node.kind === 'parallel' || node.kind === 'scope') {
          visit(node.children ?? [])
        } else {
          if (node.kind === 'step') {
            found.set(activityName(this.name, node.name), async (workflowInput, ctx) =>
              node.handler!(resolveReferences(node.inputSpec, workflowInput, checkpointsOf(ctx)), ctx))
          }
          const comp = node.compensate
          if (comp) { // a step, wait, timer or child can be undone
            found.set(activityName(this.name, node.name, true), async (workflowInput, ctx) =>
              comp.handler(resolveReferences(comp.input ?? output(node.name), workflowInput, checkpointsOf(ctx)), ctx))
          }
        }
      }
    }

    visit(this.nodes)
    for (const update of this.updates.values()) {
      const handler = update.handler
      // The engine resolved the handler's input already: its payload is passed as is.
      if (handler) found.set(updateActivityName(this.name, update.name), async (payload, ctx) => handler(payload, ctx))
    }
    return found
  }
}

/** An update handler as the blueprint sends it (each field only when set). */
function updateSpec(update: InternalUpdate): Record<string, unknown> {
  const spec: Record<string, unknown> = {}
  if (update.handler) spec.handler = true
  if (update.validate) spec.validate = update.validate.expr
  if (update.message) spec.message = update.message
  if (update.input !== undefined && update.input !== null) spec.input = template(update.input, `update ${update.name}.input`)
  if (update.result !== undefined && update.result !== null) spec.result = template(update.result, `update ${update.name}.result`)
  if (update.timeoutMs !== undefined && update.timeoutMs !== null) spec.timeout_ms = update.timeoutMs
  return spec
}

/** The activity the engine sends an update handler of an SDK workflow under. */
function updateActivityName(workflowName: string, update: string): string {
  return `${workflowName}/@update/${update}`
}

/** A retry policy as the blueprint sends it. */
function retryJson(policy: RetryPolicy): Record<string, unknown> {
  const retry: Record<string, unknown> = { attempts: policy.attempts, initial_ms: policy.initialMs, backoff: policy.backoff, maximum_ms: policy.maximumMs }
  if (policy.nonRetryable && policy.nonRetryable.length > 0) retry.non_retryable = [...policy.nonRetryable]
  return retry
}

/** The activity the engine sends a step (or its compensation) of an SDK workflow under. */
function activityName(workflowName: string, step: string, compensate = false): string {
  return compensate ? `${workflowName}/${step}/compensate` : `${workflowName}/${step}`
}

/** A workflow blueprint. `timeoutMs` is the whole run's deadline (none by default), enforced by the engine. */
export function workflow(
  name: string,
  options?: { version?: number; timeoutMs?: number; taskQueue?: string },
): WorkflowBlueprint {
  return new WorkflowBlueprint(name, options)
}

export interface LeasedTask {
  lease_token: string
  kind: 'job' | 'activity' | 'compensation' | 'update'
  id: string
  queue: string
  name: string
  attempt: number
  max_retries: number
  payload: any
  context?: RequestContext
  workflow_id?: string | null
  step_id?: string | null
  /** A step's: the outputs of the run's completed steps. */
  checkpoints?: Record<string, unknown>
  lease_until_ms: number
  /** An engine step's heartbeat timeout: call `ctx.heartbeat()` more often than this. Null for most tasks. */
  heartbeat_ms?: number | null
}

/** What a running worker's transport offers a handler's context: cancellation, without HTTP. */
export interface TaskTransport {
  cancelRequested(leaseToken: string): boolean
}

export class ExecutionContext {
  readonly task: LeasedTask
  readonly workerId: string
  readonly client: JoobQClient
  readonly context: RequestContext
  readonly leaseTtlMs: number
  private readonly transport?: TaskTransport
  private lastBeatMs = Number.NEGATIVE_INFINITY
  private beatCancel = false

  constructor(
    task: LeasedTask,
    workerId: string,
    client: JoobQClient,
    leaseTtlMs = 30000,
    transport?: TaskTransport,
  ) {
    this.transport = transport
    this.task = task
    this.workerId = workerId
    this.client = client
    this.leaseTtlMs = leaseTtlMs
    this.context = { ...(task.context ?? {}) }
  }

  get attempt(): number {
    return this.task.attempt
  }

  get dedupeKey(): string {
    const wf = this.task.workflow_id || this.task.id
    const step = this.task.step_id || this.task.name
    return `${wf}:${step}:${this.task.attempt}`
  }

  /** True when the run was cancelled. In a running worker it answers what the last lease renewal said, without
   * waiting for the gateway. For a step with `heartbeat_ms` it also tells the engine the step is alive
   * (`POST /sdk/tasks/:token/heartbeat`, at most every third of `heartbeat_ms`): the worker's own renewals do not, so
   * a handler that stops calling this is timed out. */
  async heartbeat(leaseTtlMs = this.leaseTtlMs): Promise<boolean> {
    const beatMs = this.task.heartbeat_ms
    if (beatMs) {
      const now = performance.now()
      if (now - this.lastBeatMs >= Math.max(100, Math.floor(beatMs / 3))) {
        this.lastBeatMs = now
        try {
          const res = await this.client.heartbeatTask(this.task.lease_token, this.workerId, leaseTtlMs)
          this.beatCancel = Boolean(res.cancel_requested)
        } catch {
          // The next beat tries again; the engine's deadline decides.
        }
      }
      if (this.beatCancel) return true
    }
    if (this.transport) return this.transport.cancelRequested(this.task.lease_token)
    const res = await this.client.heartbeatTask(this.task.lease_token, this.workerId, leaseTtlMs)
    return res.cancel_requested
  }

  async enqueue<TPayload>(
    jobDef: JobDefinition<TPayload, any>,
    payload: TPayload,
    options?: { jid?: string; delayMs?: number; runAtMs?: number; expiresMs?: number; timeoutMs?: number; uniqueKey?: string; uniqueMode?: string; uniqueTtlMs?: number; context?: RequestContext },
  ): Promise<{ jid: string; queue: string; status: string }> {
    return this.client.enqueue(jobDef, payload, {
      ...options,
      context: { ...this.context, ...(options?.context ?? {}) },
    })
  }

  async enqueueJob(options: EnqueueJobOptions): Promise<{ jid: string; queue: string; status: string }> {
    return this.client.enqueueJob({
      ...options,
      context: { ...this.context, ...(options.context ?? {}) },
    })
  }

  async start(
    workflowDef: WorkflowBlueprint,
    inputData?: unknown,
    options?: { id?: string; searchAttributes?: Record<string, unknown>; build?: string; context?: RequestContext },
  ): Promise<{ id: string; created: boolean; status: string }> {
    return this.client.start(workflowDef, inputData, {
      ...options,
      context: { ...this.context, ...(options?.context ?? {}) },
    })
  }

  async startWorkflow(options: {
    name: string
    input?: unknown
    context?: RequestContext
    id?: string
    searchAttributes?: Record<string, unknown>
    build?: string
  }): Promise<{ id: string; created: boolean; status: string }> {
    return this.client.startWorkflow({
      ...options,
      context: { ...this.context, ...(options.context ?? {}) },
    })
  }

  async registerSchedule(
    name: string,
    jobType: string,
    queue: string,
    options?: { cron?: string; every?: string; timezone?: string; payload?: unknown; maxRetries?: number; encryptFields?: string[]; uniqueKey?: string },
  ): Promise<{ id: string; name: string; kind: string; created: boolean }> {
    return this.client.registerSchedule(name, jobType, queue, options)
  }

  async rateLimit(key: string, limit: number, periodMs: number): Promise<{ allowed: boolean; retryAfterMs: number }> {
    return this.client.rateLimit(key, limit, periodMs)
  }

  /** `JoobQClient.createBatch`; the members and callbacks carry this handler's context. */
  async createBatch(jobs: BatchJob[], options: CreateBatchOptions = {}): Promise<BatchCreated> {
    return this.client.createBatch(jobs, { ...options, context: { ...this.context, ...(options.context ?? {}) } })
  }

  async getBatch(batchId: string): Promise<BatchStatus> {
    return this.client.getBatch(batchId)
  }

  async signalWorkflow(id: string, name: string, payload: unknown = null): Promise<{ id: string; accepted: boolean }> {
    return this.client.signalWorkflow(id, name, payload)
  }

  /** Sends an update to a running workflow (see `JoobQClient.updateWorkflow`). */
  async updateWorkflow(
    id: string,
    name: string,
    input: unknown = null,
    options?: { updateId?: string; waitMs?: number },
  ): Promise<UpdateOutcome> {
    return this.client.updateWorkflow(id, name, input, options)
  }

  async describeWorkflow(id: string): Promise<Record<string, any>> {
    return this.client.describeWorkflow(id)
  }

  async workflowResult(id: string, waitMs = 0): Promise<Record<string, any>> {
    return this.client.workflowResult(id, waitMs)
  }

  async workflowHistory(id: string, afterSeq = 0, limit = 200): Promise<Record<string, any>[]> {
    return this.client.workflowHistory(id, afterSeq, limit)
  }

  async queryWorkflow(id: string, name: string): Promise<any> {
    return this.client.queryWorkflow(id, name)
  }

  async upsertWorkflowAttributes(
    id: string,
    set: Record<string, unknown> | null = null,
    remove: string[] | null = null,
  ): Promise<Record<string, any>> {
    return this.client.upsertWorkflowAttributes(id, set, remove)
  }
}

export interface EnqueueJobOptions {
  queue: string
  jobType: string
  payload?: unknown
  context?: RequestContext
  jid?: string
  maxRetries?: number
  delayMs?: number
  runAtMs?: number
  expiresMs?: number
  timeoutMs?: number
  encryptFields?: string[]
  uniqueKey?: string
  uniqueMode?: string
  uniqueTtlMs?: number
}

/** One job of `enqueueMany` or `createBatch`: `{ job, payload, ... }` or what `enqueueJob` takes. */
export type BatchJob = EnqueueJobOptions | { job: JobDefinition<any, any>; payload: unknown; jid?: string; delayMs?: number; runAtMs?: number; expiresMs?: number; timeoutMs?: number; uniqueKey?: string; uniqueMode?: string; context?: RequestContext }

/** The callbacks of a Pro batch (`createBatch`), each a job of the shapes `BatchJob` takes. */
export interface CreateBatchOptions {
  onComplete?: BatchJob
  onSuccess?: BatchJob
  onFailure?: BatchJob
  description?: string
  context?: RequestContext
}

/** A Pro batch just created: its id, member count and each member's enqueue answer. */
export interface BatchCreated {
  batchId: string
  total: number
  jobs: Array<{ jid: string; queue: string; status: string }>
}

/** A Pro batch's progress. `status` is `pending`, then `success` (no member dead) or `complete`. */
export interface BatchStatus {
  batchId: string
  description: string | null
  status: string
  total: number
  pending: number
  succeeded: number
  failed: number
  createdAt: number
  finishedAt: number | null
}

/** One outcome for `ackTasks`: `complete` (with `output`) or `fail` (with `failureFields`). */
export type AckItem = { token: string; outcome: 'complete' | 'fail' } & Record<string, unknown>

/** The fields that report `error` to the gateway (`failTask`, and a `fail` item of `ackTasks`). */
export function failureFields(error: unknown, retryable = true): Record<string, unknown> {
  const err = error instanceof Error ? error : new Error(String(error))
  return {
    error_class: err.name || 'Error',
    error_message: (err.message || err.name || 'Error').slice(0, 4000),
    retryable,
    sdk_language: 'typescript',
    stack_frames: parseStackFrames(err.stack),
    raw_stacktrace: err.stack?.slice(0, 4000),
  }
}

export class JoobQClient {
  /**
   * Milliseconds one gateway call may take. A worker lowers it: a call that hangs for longer than a lease would let
   * every lease the worker holds expire while its tasks still run.
   */
  requestTimeoutMs = 60_000
  private readonly gatewayUrl: string
  private readonly token: string
  private readonly contextProvider?: () => RequestContext

  constructor(
    gatewayUrl: string,
    token: string,
    options?: { contextProvider?: () => RequestContext },
  ) {
    this.gatewayUrl = gatewayUrl.replace(/\/+$/, '')
    this.token = token
    this.contextProvider = options?.contextProvider
  }

  private resolveContext(explicit?: RequestContext): RequestContext {
    const ambient = this.contextProvider ? this.contextProvider() : {}
    return { ...ambient, ...(explicit ?? {}) }
  }

  async enqueue<TPayload>(
    jobDef: JobDefinition<TPayload, any>,
    payload: TPayload,
    options?: { jid?: string; delayMs?: number; runAtMs?: number; expiresMs?: number; timeoutMs?: number; uniqueKey?: string; uniqueMode?: string; uniqueTtlMs?: number; context?: RequestContext },
  ): Promise<{ jid: string; queue: string; status: string }> {
    return this.enqueueJob({
      queue: jobDef.queue,
      jobType: jobDef.name,
      payload,
      context: options?.context,
      jid: options?.jid,
      maxRetries: jobDef.retries,
      delayMs: options?.delayMs,
      runAtMs: options?.runAtMs,
      expiresMs: options?.expiresMs,
      timeoutMs: options?.timeoutMs,
      encryptFields: jobDef.encryptedFields,
      uniqueKey: options?.uniqueKey,
      uniqueMode: options?.uniqueMode,
      uniqueTtlMs: options?.uniqueTtlMs ?? jobDef.uniqueTtlMs,
    })
  }

  async enqueueJob(options: EnqueueJobOptions): Promise<{ jid: string; queue: string; status: string }> {
    return this.post('/api/v1/sdk/jobs', this.jobBody(options))
  }

  private jobBody(options: EnqueueJobOptions): Record<string, unknown> {
    return {
      queue: options.queue,
      job_type: options.jobType,
      payload: options.payload ?? {},
      context: this.resolveContext(options.context),
      jid: options.jid,
      max_retries: options.maxRetries ?? 3,
      delay_ms: options.delayMs ?? 0,
      run_at_ms: options.runAtMs,
      expires_ms: options.expiresMs,
      timeout_ms: options.timeoutMs,
      encrypt_fields: options.encryptFields ?? [],
      unique_key: options.uniqueKey,
      unique_mode: options.uniqueMode,
      unique_ttl_ms: options.uniqueTtlMs,
    }
  }

  /**
   * Enqueues many jobs with `POST /sdk/jobs/batch` (500 per call); answers one `{jid, queue, status}` per job, in
   * order. An item is `{ job, payload, jid?, delayMs?, runAtMs?, expiresMs?, timeoutMs?, uniqueKey?, uniqueMode?, context? }` or what `enqueueJob` takes.
   */
  async enqueueMany(jobs: BatchJob[]): Promise<Array<{ jid: string; queue: string; status: string }>> {
    const bodies = jobs.map((item) => this.itemBody(item))
    const out: Array<{ jid: string; queue: string; status: string }> = []
    for (let i = 0; i < bodies.length; i += 500) {
      const res = await this.post<{ jobs: Array<{ jid: string; queue: string; status: string }> }>('/api/v1/sdk/jobs/batch', {
        jobs: bodies.slice(i, i + 500),
      })
      out.push(...res.jobs)
    }
    return out
  }

  private itemBody(item: BatchJob, context?: RequestContext): Record<string, unknown> {
    if ('job' in item) {
      const def = item.job
      return this.jobBody({
        queue: def.queue, jobType: def.name, payload: item.payload, context: item.context ?? context, jid: item.jid,
        maxRetries: def.retries, delayMs: item.delayMs, runAtMs: item.runAtMs, expiresMs: item.expiresMs, timeoutMs: item.timeoutMs, encryptFields: def.encryptedFields, uniqueKey: item.uniqueKey,
        uniqueMode: item.uniqueMode, uniqueTtlMs: def.uniqueTtlMs,
      })
    }
    return this.jobBody({ ...item, context: item.context ?? context })
  }

  /**
   * Creates a Pro batch with `POST /sdk/batches`: 1 to 1000 member jobs (without a `uniqueKey`) and callback jobs.
   * `onFailure` is enqueued at the first dead member, `onComplete` once every member completed or was dead-lettered,
   * `onSuccess` then too when none was dead; each once, with `{batch: {id, kind, total, succeeded, failed}}` merged
   * into its payload. 402 pro_required without a Pro licence.
   */
  async createBatch(jobs: BatchJob[], options: CreateBatchOptions = {}): Promise<BatchCreated> {
    const body: Record<string, unknown> = {
      description: options.description ?? null,
      jobs: jobs.map((item) => this.batchItemBody(item, options.context)),
    }
    for (const [kind, callback] of [['on_complete', options.onComplete], ['on_success', options.onSuccess], ['on_failure', options.onFailure]] as const) {
      if (callback) body[kind] = this.batchItemBody(callback, options.context)
    }
    const res = await this.post<{ batch_id: string; total: number; jobs: Array<{ jid: string; queue: string; status: string }> }>('/api/v1/sdk/batches', body)
    return { batchId: res.batch_id, total: res.total, jobs: res.jobs }
  }

  /** One member or callback of `createBatch`: the batch's `context` merged key by key under the job's own (the job's keys win). */
  private batchItemBody(item: BatchJob, context?: RequestContext): Record<string, unknown> {
    return this.itemBody({ ...item, context: { ...(context ?? {}), ...(item.context ?? {}) } } as BatchJob, context)
  }

  /** A Pro batch's progress (`GET /sdk/batches/:id`). */
  async getBatch(batchId: string): Promise<BatchStatus> {
    const res = await this.get<Record<string, any>>(`/api/v1/sdk/batches/${encodeURIComponent(batchId)}`)
    return {
      batchId: res.batch_id, description: res.description ?? null, status: res.status, total: res.total,
      pending: res.pending, succeeded: res.succeeded, failed: res.failed, createdAt: res.created_at,
      finishedAt: res.finished_at ?? null,
    }
  }

  async start(
    workflowDef: WorkflowBlueprint,
    inputData?: unknown,
    options?: { id?: string; searchAttributes?: Record<string, unknown>; build?: string; context?: RequestContext },
  ): Promise<{ id: string; created: boolean; status: string }> {
    return this.startWorkflow({
      name: workflowDef.name,
      input: inputData,
      context: options?.context,
      id: options?.id,
      searchAttributes: options?.searchAttributes,
      build: options?.build,
    })
  }

  async startWorkflow(options: {
    name: string
    input?: unknown
    context?: RequestContext
    id?: string
    searchAttributes?: Record<string, unknown>
    build?: string
  }): Promise<{ id: string; created: boolean; status: string }> {
    return this.post('/api/v1/sdk/workflows', {
      name: options.name,
      input: options.input ?? null,
      context: this.resolveContext(options.context),
      id: options.id,
      search_attributes: options.searchAttributes,
      build: options.build,
    })
  }

  async signalWorkflow(id: string, name: string, payload: unknown = null): Promise<{ id: string; accepted: boolean }> {
    return this.post(`/api/v1/sdk/workflows/${encodeURIComponent(id)}/signal`, { name, payload })
  }

  /** Sends an update to a running workflow's update handler (Pro) and waits up to `waitMs` (100 to 30000, default
   * 10000) for its outcome: `{update_id, name, status, result, error, reason, message}`. `status` is `completed`,
   * `rejected` (validate failed: `reason`, `message`), `failed`, or `accepted` (a 202) when the handler had not
   * answered in time: send again with the same `updateId` to wait for the same update. */
  async updateWorkflow(
    id: string,
    name: string,
    input: unknown = null,
    options?: { updateId?: string; waitMs?: number },
  ): Promise<UpdateOutcome> {
    const body: Record<string, unknown> = { name, input: input ?? null }
    if (options?.updateId !== undefined && options.updateId !== null) body.update_id = options.updateId
    if (options?.waitMs !== undefined && options.waitMs !== null) body.wait_ms = Math.trunc(options.waitMs)
    return this.post(`/api/v1/sdk/workflows/${encodeURIComponent(id)}/updates`, body)
  }

  /** One run (Pro; 402 without a licence): `{id, name, status, closed, run, started_at, closed_at, continued_to, output,
   * failure, attributes, queries}`. Payload fields with secret-looking names are masked, as in the console. */
  async describeWorkflow(id: string): Promise<Record<string, any>> {
    return this.get(`/api/v1/sdk/workflows/${encodeURIComponent(id)}`)
  }

  /** The run at the end of the workflow's continue-as-new chain (Pro; 402 without a licence), waiting up to `waitMs`
   * (at most 25000) for it to close; same shape as `describeWorkflow`. `closed` false means it was still open when the
   * wait ended. */
  async workflowResult(id: string, waitMs = 0): Promise<Record<string, any>> {
    return this.get(`/api/v1/sdk/workflows/${encodeURIComponent(id)}/result?wait_ms=${Math.trunc(waitMs)}`)
  }

  /** The run's events after `afterSeq` (Pro; 402 without a licence), at most `limit`, oldest first. */
  async workflowHistory(id: string, afterSeq = 0, limit = 200): Promise<Record<string, any>[]> {
    const res = await this.get<{ items?: Record<string, any>[] }>(
      `/api/v1/sdk/workflows/${encodeURIComponent(id)}/history?after_seq=${Math.trunc(afterSeq)}&limit=${Math.trunc(limit)}`,
    )
    return res.items ?? []
  }

  /** Asks the run a read-only question (Pro; 402 without a licence); returns the answer. */
  async queryWorkflow(id: string, name: string): Promise<any> {
    const res = await this.post<{ result?: unknown }>(`/api/v1/sdk/workflows/${encodeURIComponent(id)}/query`, { name })
    return res.result ?? null
  }

  /** Sets and/or removes search attributes of the workflow's open run (Pro; 402 without a licence); returns
   * `{id, attributes}`. */
  async upsertWorkflowAttributes(
    id: string,
    set: Record<string, unknown> | null = null,
    remove: string[] | null = null,
  ): Promise<Record<string, any>> {
    return this.post(`/api/v1/sdk/workflows/${encodeURIComponent(id)}/search-attributes`, { set, remove })
  }

  /** Consumes one token from the distributed rate limiter `key` (at most `limit` per `periodMs`). `allowed` is false
   * when the window is exhausted; `retryAfterMs` says how long until a token frees up. */
  async rateLimit(key: string, limit: number, periodMs: number): Promise<{ allowed: boolean; retryAfterMs: number }> {
    const res = await this.post<{ allowed: boolean; retry_after_ms: number }>('/api/v1/sdk/rate-limit', {
      key,
      limit,
      period_ms: periodMs,
    })
    return { allowed: res.allowed, retryAfterMs: res.retry_after_ms }
  }

  /** Registers a recurring job schedule. Pass exactly one of `cron` or `every` (`every` is `"<count> <unit>"`, e.g.
   * `"3 seconds"`). The gateway keeps one schedule per `name`. */
  async registerSchedule(
    name: string,
    jobType: string,
    queue: string,
    options?: { cron?: string; every?: string; timezone?: string; payload?: unknown; maxRetries?: number; encryptFields?: string[]; uniqueKey?: string },
  ): Promise<{ id: string; name: string; kind: string; created: boolean }> {
    return this.post('/api/v1/sdk/schedules', {
      name,
      kind: 'job',
      cron: options?.cron,
      every: options?.every,
      timezone: options?.timezone ?? 'UTC',
      queue,
      job_type: jobType,
      payload: options?.payload ?? {},
      max_retries: options?.maxRetries ?? 3,
      encrypt_fields: options?.encryptFields ?? [],
      unique_key: options?.uniqueKey,
    })
  }

  /** Sends a workflow's blueprint; the gateway keeps each new content hash (`created`) and ignores a known one. */
  async registerBlueprint(
    workflowDef: WorkflowBlueprint,
    workerId?: string,
  ): Promise<{ name: string; blueprint_hash: string; created: boolean; definition: string | null }> {
    return this.post('/api/v1/sdk/blueprints', {
      name: workflowDef.name,
      sdk_language: 'typescript',
      worker_id: workerId ?? null,
      blueprint: workflowDef.toBlueprint(),
    })
  }

  async registerWorker(options: {
    workerId: string
    taskQueues: string[]
    concurrency?: number
    serviceName?: string
    team?: string
  }): Promise<{ worker_id: string; status: string; ttl_ms: number }> {
    return this.post('/api/v1/sdk/workers/register', {
      worker_id: options.workerId,
      sdk_language: 'typescript',
      sdk_version: SDK_VERSION,
      service_name: options.serviceName,
      team: options.team ?? process.env.JOOBQ_TEAM,
      host: hostname(),
      pid: process.pid,
      task_queues: options.taskQueues,
      concurrency: options.concurrency ?? 4,
      delivery_mode: 'poll',
    })
  }

  async deregisterWorker(workerId: string): Promise<{ worker_id: string; status: string; ttl_ms: number }> {
    return this.post(`/api/v1/sdk/workers/${encodeURIComponent(workerId)}/deregister`, {})
  }

  async pollTasks(options: {
    workerId: string
    taskQueues: string[]
    maxTasks?: number
    timeoutMs?: number
    leaseTtlMs?: number
  }): Promise<LeasedTask[]> {
    const res = await this.post<{ tasks: LeasedTask[] }>('/api/v1/sdk/tasks/poll', {
      worker_id: options.workerId,
      task_queues: options.taskQueues,
      max_tasks: options.maxTasks ?? 1,
      timeout_ms: options.timeoutMs ?? 0,
      lease_ttl_ms: options.leaseTtlMs ?? 30000,
    })
    return res.tasks
  }

  async heartbeatTask(
    leaseToken: string,
    workerId: string,
    leaseTtlMs = 30000,
  ): Promise<{ cancel_requested: boolean; lease_until_ms: number }> {
    return this.post(`/api/v1/sdk/tasks/${encodeURIComponent(leaseToken)}/heartbeat`, {
      worker_id: workerId,
      lease_ttl_ms: leaseTtlMs,
    })
  }

  async completeTask(
    leaseToken: string,
    workerId: string,
    output: unknown = null,
  ): Promise<{ lease_token: string; status: string }> {
    return this.post(`/api/v1/sdk/tasks/${encodeURIComponent(leaseToken)}/complete`, {
      worker_id: workerId,
      output,
    })
  }

  async failTask(
    leaseToken: string,
    workerId: string,
    error: unknown,
    retryable = true,
  ): Promise<{ lease_token: string; status: string }> {
    return this.post(`/api/v1/sdk/tasks/${encodeURIComponent(leaseToken)}/fail`, {
      worker_id: workerId,
      ...failureFields(error, retryable),
    })
  }

  /** Settles up to 100 leases in one call (`POST /sdk/tasks/ack`); each item gets its own result. */
  async ackTasks(
    workerId: string,
    items: AckItem[],
  ): Promise<{ results: Array<{ lease_token: string; status: string; error: { status: number; code: string; message: string } | null }> }> {
    return this.post('/api/v1/sdk/tasks/ack', { worker_id: workerId, items })
  }

  /** Renews many leases in one call (`POST /sdk/tasks/heartbeat`). */
  async heartbeatTasks(
    workerId: string,
    leases: Array<{ token: string }>,
    leaseTtlMs = 30000,
  ): Promise<{ leases: Array<{ lease_token: string; cancel_requested: boolean; lease_until_ms: number; error: unknown }> }> {
    return this.post('/api/v1/sdk/tasks/heartbeat', { worker_id: workerId, lease_ttl_ms: leaseTtlMs, leases })
  }

  private async post<R>(path: string, body: unknown): Promise<R> {
    return this.send<R>('POST', path, body)
  }

  private async get<R>(path: string): Promise<R> {
    return this.send<R>('GET', path, undefined)
  }

  private async send<R>(method: 'GET' | 'POST', path: string, body: unknown): Promise<R> {
    const headers: Record<string, string> = {
      Authorization: `Bearer ${this.token}`,
      'X-JoobQ-SDK': `typescript/${SDK_VERSION}`,
    }
    if (body !== undefined) headers['Content-Type'] = 'application/json'
    const res = await fetch(`${this.gatewayUrl}${path}`, {
      method,
      headers,
      body: body === undefined ? undefined : JSON.stringify(body),
      signal: AbortSignal.timeout(Math.max(1, Math.floor(this.requestTimeoutMs))), // whole milliseconds only
    })
    if (res.status === 426) throw new SdkTooOldError(res.status, await res.text().catch(() => '')) // unreadable: still this error
    if (!res.ok) {
      throw new GatewayError(res.status, await res.text())
    }
    return (await res.json()) as R
  }
}

export interface WorkerOptions {
  workerId: string
  taskQueues?: string[]
  concurrency?: number
  serviceName?: string
  team?: string
  leaseTtlMs?: number
  pollTimeoutMs?: number
  drainTimeoutMs?: number
  /** Leases held beyond the free slots, so a handler that finishes finds its next task at once (default concurrency / 2). */
  prefetch?: number
  /** Outcomes queued for the acker before handlers wait for it (default 4 x concurrency). */
  ackBuffer?: number
  /** How long the acker waits for more outcomes before it sends a batch (default 5 ms). */
  ackLingerMs?: number
  /** Stop on SIGTERM/SIGINT (default true). */
  handleSignals?: boolean
}

const sleep = (ms: number) => new Promise<void>((r) => setTimeout(r, ms))

/** Something to wait for, with a time limit: `wake()` resolves every current `wait`, or the next one when none waits. */
class Waker {
  private waiters: Array<() => void> = []
  private pending = false

  wait(ms: number): Promise<void> {
    if (this.pending) {
      this.pending = false
      return Promise.resolve()
    }
    return new Promise<void>((resolve) => {
      const timer = setTimeout(done, Math.max(0, ms))
      const self = this
      function done() {
        clearTimeout(timer)
        self.waiters = self.waiters.filter((w) => w !== done)
        resolve()
      }
      this.waiters.push(done)
    })
  }

  wake(): void {
    const waiting = this.waiters
    this.waiters = []
    this.pending = waiting.length === 0
    for (const w of waiting) w()
  }
}

/**
 * In-app worker: runs up to `concurrency` jobs and workflow steps at once inside the booted application, and on
 * SIGTERM/SIGINT (or `stop()`) drains the running tasks, sends their outcomes and deregisters.
 *
 * Its gateway calls run beside the handlers, never in their way: a poll loop keeps a small buffer of leased tasks (free
 * slots plus `prefetch`), an ack loop sends the outcomes handlers queue (`POST /sdk/tasks/ack`, up to 100 per call,
 * after at most `ackLingerMs`, retried while the gateway is unavailable; a task stays leased until its outcome is
 * acknowledged; when `ackBuffer` outcomes wait, handlers wait), and one timer renews every lease the worker holds
 * (`POST /sdk/tasks/heartbeat`).
 */
/** True when `p` settled within `ms`; the timer does not keep the process alive afterwards. */
async function within(p: Promise<unknown>, ms: number): Promise<boolean> {
  let timer: ReturnType<typeof setTimeout> | undefined
  const timeout = new Promise<boolean>((r) => {
    timer = setTimeout(() => r(false), Math.max(0, ms))
  })
  try {
    return await Promise.race([p.then(() => true), timeout])
  } finally {
    clearTimeout(timer)
  }
}

export class JoobQWorker {
  readonly client: JoobQClient
  private readonly options: WorkerOptions & { taskQueues: string[] }
  private readonly handlers = new Map<string, TaskHandler>()
  private readonly middlewares: TaskMiddleware[] = []
  private readonly workflows = new Map<string, WorkflowBlueprint>()
  private readonly blueprintsSent = new Set<string>()
  private running = false
  // The transport: every lease held (buffered, running or waiting for its ack), the buffer, the outcome queue.
  private transportOn = false
  private readonly leased = new Map<string, LeasedTask>()
  private readonly cancelled = new Map<string, boolean>()
  private readonly ready: LeasedTask[] = []
  private readonly acks: AckItem[] = []
  private held = 0 // buffered + running
  private active = 0 // running
  private ackClosing = false
  private giveUp = false
  private beatStop = false
  private readonly changed = new Waker()
  private readonly ackSpace = new Waker()
  private readonly ackArrived = new Waker()
  private readonly beatWake = new Waker()
  private readonly taskTransport: TaskTransport = {
    cancelRequested: (token) => this.cancelled.get(token) ?? false,
  }

  constructor(client: JoobQClient, options: WorkerOptions) {
    this.client = client
    this.options = { ...options, taskQueues: [...(options.taskQueues ?? [])] }
    // One hung call must not outlast the leases: a poll waits `pollTimeoutMs` at the gateway, and a sixth of a lease
    // on top keeps a renewal that hangs well inside the lease (10 s with the defaults).
    const bound = Math.floor((options.pollTimeoutMs ?? 5000) + (options.leaseTtlMs ?? 30000) / 6)
    if (client.requestTimeoutMs > bound) client.requestTimeoutMs = bound
  }

  private refused = 0
  private fatal: SdkTooOldError | undefined // set: the gateway refuses this SDK's version, the worker stops

  /** Stops the worker for good: the gateway refuses this SDK's version, so no call can succeed. Logs one line. */
  private fatalStop(err: SdkTooOldError): void {
    if (this.fatal) return
    this.fatal = err
    console.error(err.logLine())
    this.giveUp = true
    this.ackClosing = true
    this.beatStop = true
    this.stop()
    this.ackSpace.wake()
    this.ackArrived.wake()
    this.beatWake.wake()
  }

  /**
   * Says once, on stderr, that the gateway refuses this worker (a wrong or rotated token, no Pro key): it goes on
   * retrying, and without this line it would sit idle with nothing in its output.
   */
  private reportRefusal(what: string, err: unknown): void {
    if (!(err instanceof GatewayError) || err.status < 400 || err.status >= 500 || err.status === 408 || err.status === 429) return
    if (this.refused === err.status) return
    this.refused = err.status
    console.error(`joobq: the gateway refuses this worker (${what}): ${err.message}. Retrying; check the SDK token and the server's licence.`)
  }

  private get concurrency(): number {
    return Math.max(1, this.options.concurrency ?? 4)
  }

  private get prefetch(): number {
    return Math.max(0, this.options.prefetch ?? Math.max(1, Math.floor(this.concurrency / 2)))
  }

  private get ackBuffer(): number {
    return Math.max(1, this.options.ackBuffer ?? 4 * this.concurrency)
  }

  private get leaseTtlMs(): number {
    return this.options.leaseTtlMs ?? 30000
  }

  use(mw: TaskMiddleware): this {
    this.middlewares.push(mw)
    return this
  }

  registerJob(jobDef: JobDefinition<any, any>): this {
    if (jobDef.queue && !this.options.taskQueues.includes(jobDef.queue)) {
      this.options.taskQueues.push(jobDef.queue)
    }
    this.handlers.set(jobDef.name, jobDef.perform as TaskHandler)
    return this
  }

  registerWorkflow(workflowDef: WorkflowBlueprint): this {
    if (workflowDef.taskQueue && !this.options.taskQueues.includes(workflowDef.taskQueue)) {
      this.options.taskQueues.push(workflowDef.taskQueue)
    }
    this.workflows.set(workflowDef.name, workflowDef)
    // The engine conducts the workflow's runs and sends each step as its own task.
    for (const [name, handler] of workflowDef.activities()) this.handlers.set(name, handler)
    return this
  }

  handleJob<TPayload = any, TResult = unknown>(name: string, handler: TaskHandler<TPayload, TResult>): this {
    this.handlers.set(name, handler as TaskHandler)
    return this
  }

  async processTask(task: LeasedTask): Promise<{ status: string; output?: unknown }> {
    const workerId = this.options.workerId
    const handler = this.handlers.get(task.name)
    if (!handler) {
      await this.settle({ token: task.lease_token, outcome: 'fail', ...failureFields(new NonRetryableError(`No handler registered for ${task.name} [JQ-901] https://joobq.io/errors/JQ-901`), false) })
      return { status: 'failed' }
    }
    // Everything that can throw for this task is inside the try: a task with no outcome keeps its lease renewed for
    // ever.
    let output: unknown
    try {
      const ctx = new ExecutionContext(task, workerId, this.client, this.leaseTtlMs, this.transportOn ? this.taskTransport : undefined)

      let idx = -1
      const dispatch = async (i: number): Promise<unknown> => {
        if (i <= idx) throw new Error('next() called multiple times')
        idx = i
        const mw = this.middlewares[i]
        if (mw) return mw(ctx, () => dispatch(i + 1))
        return handler(task.payload, ctx)
      }

      output = await dispatch(0)
    } catch (err) {
      const retryable = !(err instanceof NonRetryableError)
      await this.settle({ token: task.lease_token, outcome: 'fail', ...failureFields(err, retryable) })
      return { status: 'failed' }
    }
    await this.settle({ token: task.lease_token, outcome: 'complete', output: output ?? null })
    return { status: 'completed', output }
  }

  /** Queues an outcome for the ack loop (waiting while the queue is full); outside a running worker it is sent here. */
  private async settle(item: AckItem): Promise<void> {
    if (this.fatal) return // the gateway refuses this SDK: the outcome is left to its lease
    if (!this.transportOn) {
      await this.report(() => this.client.ackTasks(this.options.workerId, [item]))
      return
    }
    while (this.acks.length >= this.ackBuffer && !this.giveUp) await this.ackSpace.wait(500)
    if (this.giveUp) return // left to its lease
    this.acks.push(item)
    this.ackArrived.wake()
  }

  /** Sends an outcome, retrying while the gateway is unavailable; a lost outcome is left to the lease. */
  private async report(call: () => Promise<unknown>): Promise<void> {
    let delay = 250
    for (let i = 0; i < 6; i++) {
      try {
        await call()
        return
      } catch (err) {
        if (err instanceof GatewayError && err.status < 500) return
      }
      await sleep(delay)
      delay = Math.min(delay * 2, 5000)
    }
  }

  private async register(): Promise<void> {
    await this.registerBlueprints() // first: a worker that shows up has its blueprints in
    await this.client.registerWorker({
      workerId: this.options.workerId,
      taskQueues: this.options.taskQueues,
      concurrency: this.concurrency,
      serviceName: this.options.serviceName,
      team: this.options.team,
    })
  }

  /** Registers every workflow's blueprint once; one the gateway refuses (4xx) is logged and not sent again. */
  private async registerBlueprints(): Promise<void> {
    for (const [name, wf] of this.workflows) {
      if (this.blueprintsSent.has(name)) continue
      try {
        await this.client.registerBlueprint(wf, this.options.workerId)
      } catch (err) {
        if (!(err instanceof GatewayError) || err.status >= 500 || err instanceof SdkTooOldError) throw err
        console.error(`joobq: blueprint of ${name} refused: ${err.message} [JQ-902] https://joobq.io/errors/JQ-902`)
      }
      this.blueprintsSent.add(name)
    }
  }

  private release(token: string): void {
    this.leased.delete(token)
    this.cancelled.delete(token)
  }

  /** Starts buffered tasks while slots are free. */
  private dispatch(): void {
    while (this.active < this.concurrency && this.ready.length > 0 && !this.fatal) {
      const task = this.ready.shift() as LeasedTask
      this.active++
      this.processTask(task)
        .catch((err) => console.error(`joobq: task ${task.id} could not be settled: ${err}`))
        .finally(() => {
          this.active--
          this.held--
          this.changed.wake()
          this.dispatch()
        })
    }
  }

  private async pollLoop(pollIntervalMs: number): Promise<void> {
    const capacity = this.concurrency + this.prefetch
    let backoff = pollIntervalMs
    while (this.running) {
      if (this.held >= capacity) {
        await this.changed.wait(500)
        continue
      }
      let tasks: LeasedTask[]
      try {
        tasks = await this.client.pollTasks({
          workerId: this.options.workerId,
          taskQueues: this.options.taskQueues,
          maxTasks: Math.min(capacity - this.held, 100),
          timeoutMs: this.options.pollTimeoutMs ?? 5000,
          leaseTtlMs: this.leaseTtlMs,
        })
        backoff = pollIntervalMs
        this.refused = 0
      } catch (err) {
        if (err instanceof SdkTooOldError) {
          this.fatalStop(err)
          return
        }
        this.reportRefusal('poll for tasks', err)
        await this.changed.wait(backoff + Math.random() * 100)
        backoff = Math.min(backoff * 2, 5000)
        continue
      }
      for (const task of tasks) {
        this.leased.set(task.lease_token, task)
        this.ready.push(task)
      }
      this.held += tasks.length
      this.dispatch()
    }
  }

  private async ackLoop(): Promise<void> {
    const linger = this.options.ackLingerMs ?? 5
    while (!this.fatal) {
      if (this.acks.length === 0) {
        if (this.ackClosing) return
        await this.ackArrived.wait(100)
        continue
      }
      if (this.acks.length < 100 && linger > 0 && !this.ackClosing) await sleep(linger)
      const batch = this.acks.splice(0, 100)
      this.ackSpace.wake()
      await this.sendAcks(batch)
    }
  }

  private async sendAcks(batch: AckItem[]): Promise<void> {
    let delay = 250
    while (!this.fatal) {
      // refused meanwhile: nothing more is sent, the leases bring these back
      try {
        await this.client.ackTasks(this.options.workerId, batch)
        break // a refused item (its lease is gone) is not sent again either
      } catch (err) {
        if (err instanceof SdkTooOldError) {
          this.fatalStop(err)
          break
        }
        if (err instanceof GatewayError && err.status === 413 && batch.length > 1) {
          // too large for one call: in halves
          const half = Math.floor(batch.length / 2)
          await this.sendAcks(batch.slice(0, half))
          await this.sendAcks(batch.slice(half))
          return
        }
        if (err instanceof GatewayError && err.status < 500 && err.status !== 429) {
          console.error(`joobq: the gateway refused ${batch.length} outcomes: ${err.message}`)
          break
        }
      }
      if (this.giveUp) break // shutting down: the leases bring these tasks back
      await this.changed.wait(delay)
      delay = Math.min(delay * 2, 5000)
    }
    for (const item of batch) this.release(item.token)
  }

  private async heartbeatLoop(): Promise<void> {
    const every = Math.max(500, Math.floor(this.leaseTtlMs / 3))
    let nextAll = Date.now() + every
    let lastRegister = Date.now()
    while (!this.beatStop) {
      await this.beatWake.wait(nextAll - Date.now())
      if (this.beatStop) return
      if (Date.now() < nextAll) continue
      const tokens = [...this.leased.keys()]
      for (let i = 0; i < tokens.length; i += 500) {
        const chunk = tokens.slice(i, i + 500)
        try {
          const res = await this.client.heartbeatTasks(this.options.workerId, chunk.map((t) => ({ token: t })), this.leaseTtlMs)
          for (const lease of res.leases) {
            if (lease.error) this.leased.delete(lease.lease_token) // gone: its outcome will be refused
            else if (this.leased.has(lease.lease_token)) this.cancelled.set(lease.lease_token, lease.cancel_requested)
          }
        } catch (err) {
          if (err instanceof SdkTooOldError) return this.fatalStop(err)
          // renewed with the next heartbeat
        }
      }
      nextAll = Date.now() + every
      if (this.running && Date.now() - lastRegister > 10000) {
        lastRegister = Date.now()
        await this.register().catch((err) => {
          if (err instanceof SdkTooOldError) this.fatalStop(err)
        })
      }
    }
  }

  /** Runs until `stop()` or SIGTERM/SIGINT; resolves once the running tasks are done, their outcomes sent and the
   * worker deregistered. Rejects with `SdkTooOldError` (without draining or deregistering) when the gateway refuses
   * this SDK's version. */
  async start(pollIntervalMs = 250): Promise<void> {
    this.fatal = undefined
    this.running = true
    const onSignal = () => {
      this.stop()
    }
    if (this.options.handleSignals !== false) {
      process.once('SIGTERM', onSignal)
      process.once('SIGINT', onSignal)
    }
    let backoff = pollIntervalMs
    while (this.running) {
      try {
        await this.register()
        this.refused = 0
        break
      } catch (err) {
        if (err instanceof SdkTooOldError) {
          this.fatalStop(err)
          break
        }
        this.reportRefusal('register', err)
        await this.changed.wait(backoff)
        backoff = Math.min(backoff * 2, 5000)
      }
    }
    if (this.fatal) return this.endFatal(onSignal)
    this.transportOn = true
    this.ackClosing = this.giveUp = this.beatStop = false
    const acker = this.ackLoop()
    const beat = this.heartbeatLoop()
    await this.pollLoop(pollIntervalMs)
    // The drain. A refusal (426), before it or during it (on an outcome or a heartbeat), ends it at once: the gateway
    // refuses every call of this SDK, so outcomes would be refused too; the leases bring the tasks back. A handler
    // already running finishes on its own.
    const deadline = Date.now() + (this.options.drainTimeoutMs ?? 30000)
    while (this.held > 0 && Date.now() < deadline && !this.fatal) {
      await this.changed.wait(Math.min(50, deadline - Date.now()))
    }
    this.ackClosing = true
    this.ackArrived.wake()
    if (!this.fatal && !(await within(acker, deadline - Date.now()))) {
      this.giveUp = true
      this.ackSpace.wake()
      this.changed.wake()
      if (!this.fatal) await within(acker, 5000)
    }
    this.giveUp = true
    this.beatStop = true
    this.beatWake.wake()
    await within(this.fatal ? Promise.all([acker, beat]) : beat, this.fatal ? 1000 : 5000)
    this.transportOn = false
    if (this.fatal) return this.endFatal(onSignal)
    process.removeListener('SIGTERM', onSignal)
    process.removeListener('SIGINT', onSignal)
    try {
      await this.client.deregisterWorker(this.options.workerId)
    } catch {}
  }

  private endFatal(onSignal: () => void): never {
    process.removeListener('SIGTERM', onSignal)
    process.removeListener('SIGINT', onSignal)
    throw this.fatal as SdkTooOldError
  }

  /** Stops polling; `start()` resolves after the running tasks finish and their outcomes are acknowledged. */
  stop(): void {
    this.running = false
    this.changed.wake()
  }
}


export function parseStackFrames(stack?: string): PolyglotFrame[] {
  if (!stack) return []
  const frames: PolyglotFrame[] = []
  for (const line of stack.split('\n')) {
    const match = line.match(/at\s+(?:(.+?)\s+\()?([^()]+):(\d+):\d+\)?/)
    if (match) {
      frames.push({
        function: match[1] || '<anonymous>',
        file: match[2],
        line: parseInt(match[3], 10),
      })
    }
  }
  return frames
}
